{
  "candidate_hash": "",
  "check_receipts": [],
  "findings": [
    {
      "message": "Scope: validate UTF-8 and keys, then match literal strings using local data. Risks: normalization, over-filtering punctuation, and mutating caller keys. Acceptance covers malformed bytes, forbidden runes, emoji, case differences, and unchanged input.",
      "requirement": "R1",
      "severity": "info"
    },
    {
      "message": "Scope: check rune boundaries and choose the longest boundary-valid match at each @. Risks: byte-based classification, unknown identifier prefixes, and rejecting valid shorter fallbacks. Acceptance covers Unicode boundary classes, dot/plus punctuation, overlapping keys, and cursor advancement.",
      "requirement": "R2",
      "severity": "info"
    },
    {
      "message": "Scope: scan in source order and append each key only on its first eligible occurrence. Risk: candidate sorting or duplicate registration affecting output order. Acceptance permutes registrations and repeats mentions, including inputs with no eligible matches.",
      "requirement": "R3",
      "severity": "info"
    },
    {
      "message": "Scope: track backtick-run length within each eligible line. Risks: mismatched runs closing spans or unmatched spans leaking across lines. Acceptance covers equal and unequal run lengths, mentions around closed spans, and unmatched spans followed by another line.",
      "requirement": "R4",
      "severity": "info"
    },
    {
      "message": "Scope: maintain fence character and opening length across LF/CRLF lines. Risks: accepting invalid indentation, shorter closers, or trailing info on closers. Acceptance covers both fence characters, opening info strings, strict closing syntax, and unclosed fences.",
      "requirement": "R5",
      "severity": "info"
    },
    {
      "message": "Scope: ignore quoted lines before fence processing and check backslash parity before ordinary left boundaries. Risks: quoted markers changing fence state or even backslash runs suppressing mentions. Acceptance covers indentation, email forms, odd/even runs, and ordinary quote marks.",
      "requirement": "R6",
      "severity": "info"
    },
    {
      "message": "Scope: Route uses Extract and maps Human Pending/Busy/Finished to start/soon/new. Risks: implicit broadcasts, reordered deliveries, or finished comments failing to request new execution. Acceptance checks all three mappings and empty or excluded mentions.",
      "requirement": "R7",
      "severity": "info"
    },
    {
      "message": "Scope: allow Agent only in Busy and fail closed on unknown values. Keep router.go self-contained with permitted imports and call-local state. Acceptance covers the routing matrix, concurrent calls, exact API, and host restrictions on files, initialization, directives, and imports.",
      "requirement": "R8",
      "severity": "info"
    }
  ],
  "manifest": [],
  "requirement_evidence": [
    {
      "assessment": "Plan exact UTF-8 validation and literal identity while preserving caller-owned keys.",
      "evidence": "Reject invalid UTF-8 text before scanning. Ignore empty or invalid UTF-8 keys and keys containing Unicode whitespace/control, @, backslash or backtick. Build a private deduplicated candidate slice. Acceptance should exercise malformed bytes, valid replacement runes, punctuation, emoji, forbidden runes, distinct case/normalization forms, and unchanged key input."
      ,
      "id": "R1"
    },
    {
      "assessment": "Plan rune-aware boundaries and longest matching candidate selection at each eligible @.",
      "evidence": "Use exact prefix comparisons and decode adjacent runes. Reject left letters/numbers/marks or underscore, hyphen, dot, plus, @; reject right letters/numbers/marks or underscore/hyphen. Examine candidates longest-first, checking each candidate's right boundary before choosing. Acceptance covers unknown identifier suffixes, dot/plus punctuation, longer known keys, a longer boundary-invalid candidate with a valid shorter fallback, and advancement past the chosen mention.",
      "id": "R2"
    },
    {
      "assessment": "Plan source-order output with per-call duplicate suppression.",
      "evidence": "Traverse eligible source positions from left to right. Maintain a local seen set and append a chosen key only once; still advance past repeated mentions. Acceptance should compare results across registration permutations, duplicated registrations, repeated mentions separated by excluded content, and zero-match inputs. An empty result may be nil.",
      "id": "R3"
    },
    {
      "assessment": "Plan independent per-line inline-code state using exact backtick-run lengths.",
      "evidence": "Outside fences and quoted lines, count each complete backtick run. An opening run hides content until an exactly equal run; other lengths remain inside the span. Reset inline state at each newline. Acceptance covers single/multiple backticks, mismatched runs, adjacent eligible mentions, unmatched runs, and eligibility on the next line. Other inline Markdown syntax receives no special treatment.",
      "id": "R4"
    },
    {
      "assessment": "Plan persistent fence state with strict opener/closer recognition and LF/CRLF handling.",
      "evidence": "Recognize openers after zero to three ASCII spaces with at least three identical backticks or tildes; ignore arbitrary opening info. Close only with the same character, sufficient run length, and ASCII space/tab suffix. Ignore all fence lines/content. Acceptance covers indentation limits, tabs, both characters, longer/shorter runs, trailing junk, unclosed fences, LF/CRLF equivalence, and preservation of standalone CR characters.",
      "id": "R5"
    },
    {
      "assessment": "Plan quotation precedence and escape parity before ordinary mention boundary checks.",
      "evidence": "First ignore any line whose first non-space/tab character is >, including while fenced; such lines never change fence state. For each @ outside excluded content, count consecutive preceding backslashes: odd suppresses it, even continues to ordinary boundary checks. Acceptance covers quoted fence openers/closers, varied indentation, zero through several backslashes, alice@example, alice+tag@example, and mentions inside ordinary quote marks.",
      "id": "R6"
    },
    {
      "assessment": "Plan one ordered delivery per extracted mention for each valid Human state.",
      "evidence": "For permitted Human calls, invoke Extract and map Pending to start, Busy to soon, and Finished to new. Preserve Extract order and uniqueness. Acceptance should verify exact Key/When values for all three states, multiple targets, duplicate mentions, and no deliveries for absent, invalid, quoted, fenced, inline-code, or escaped mentions. Finished must explicitly produce new for eligible mentions.",
      "id": "R7"
    },
    {
      "assessment": "Plan fail-closed Agent routing, exact API, restricted scope, and concurrency-safe local state.",
      "evidence": "Allow Agent only in Busy with soon; reject unknown State or Author values. Acceptance should cover every defined author/state pair, unknown and empty values, literal justification for every delivery, and concurrent calls. Host inspection must confirm only router.go changes, package mentionroute and exact API/constants, permitted imports, no init/TestMain/directives/dot or blank imports, no initializer calls, and no subprocess/network work.",
      "id": "R8"
    }
  ],
  "requirements": [
    "R1",
    "R2",
    "R3",
    "R4",
    "R5",
    "R6",
    "R7",
    "R8"
  ],
  "review_receipt": "",
  "role": "planner",
  "spec_hash": "2b8c630fccf8720b1cb3e0dd12b6f691031ec9873371f033dd4b5fdeff70c7e0",
  "summary": "Plan router.go with local UTF-8/key validation, a line/fence/inline scanner, literal rune-aware matching, source-order deduplication, and fail-closed routing. Host confirms plan stage, round 1, matching specification hash, empty candidate, and no violations. Coverage is prospective acceptance guidance from the supplied fixed specification. No files changed, implementation approved, or checks run; host verification must establish acceptance.",
  "verdict": "plan"
}

